contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint am) public {
        require(am > 0);
        c.SetMinSum(am); if (__ESBMC_reverted()) return; // MinSum = am > 0 = recorded balance of this contract
        uint balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint etherBefore = address(c).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == balBefore && address(c).balance == etherBefore);
    }
    receive() external payable {}
}

