import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 am) internal {
        vm.assume(am > 0);
        try c.SetMinSum(am) {} catch { return; }
        uint256 balBefore;
        try c.balances(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint etherBefore = address(c).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) == balBefore && address(c).balance == etherBefore);
    }

    function testFuzz_run(uint256 am) public {
        _run(am);
    }

    receive() external payable {}
}
